 * @description cmb_FUTOPT_LIST_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_FUTOPT_LIST_TP_CD_onselchange = function() {
    try {
        if (cmb_FUTOPT_LIST_TP_CD.getValue() !== "") {
            cmb_ListDdTp.setValue(cmb_FUTOPT_LIST_TP_CD.getValue());
            cmb_ListDdTp.setDisabled(true);
        } else {
            cmb_ListDdTp.setValue("K");
            cmb_ListDdTp.setDisabled(false);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS25500.cmb_FUTOPT_LIST_TP_CD_onselchange" });
    }
};

