///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name ins_search
 * @description 주권조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!await scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20210528
    btn_search.setDisabled(true);
    btn_search.setBackgroundImage("../img/btn_select_d.gif");
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCombo
 * @description 콤보박스 만들기
 * @returns {void}
 * @hidden N
 */
scwin.setCombo = function() {
    ins_combo_set(dts_FUTOPT_LIST_TP_CD, "ULDINS25500.xml", SCREN_PROCS_TP_CD_01, "03409", "ALL"); // 시장구분
    ins_combo_set(dts_FUTOPT_UPCLSS_CD, "ULDINS25500.xml", SCREN_PROCS_TP_CD_01, "02512", "ALL"); // 선물옵션구분

};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    const sToday = $c.ut.cGetToday2();
    edt_FROM_STD_CD_GRNT_DD.setValue($c.ut.cGetPlusDate2($c.ut.cGetMinusYear(sToday, 1), 1));
    edt_TO_STD_CD_GRNT_DD.setValue(sToday);
};

/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_List.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 사전체크
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkValid = async function() {
    // 시장구분이 [전체, KSE] 선택 시 KSE상장일 필수 및 6개월 제한.
    const sListTp = cmb_FUTOPT_LIST_TP_CD.getValue();
    if (sListTp === "" || sListTp === "K") {
        if ((edt_FROM_LIST_DD.getValue() === "" || edt_TO_LIST_DD.getValue() === "") &&
            (edt_FROM_STD_CD_GRNT_DD.getValue() === "" || edt_TO_STD_CD_GRNT_DD.getValue() === "")) {
            await $c.win.alert(" 시장구분이 [전체, KSE] 인 경우 \n 코드부여일 또는 상장일을 1년 이내로 입력해야 합니다.");
            edt_FROM_STD_CD_GRNT_DD.focus();
            return false;
        } else {
            // 코드부여일
            if ((edt_FROM_STD_CD_GRNT_DD.getValue() !== "" && edt_TO_STD_CD_GRNT_DD.getValue() !== "") &&
                Number($c.ut.cGetPlusYear(edt_FROM_STD_CD_GRNT_DD.getValue(), 1)) < Number(edt_TO_STD_CD_GRNT_DD.getValue())) {
                await $c.win.alert("코드부여일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_FROM_STD_CD_GRNT_DD.focus();
                return false;
            }

            // 상장일
            if ((edt_FROM_LIST_DD.getValue() !== "" && edt_TO_LIST_DD.getValue() !== "") &&
                Number($c.ut.cGetPlusYear(edt_FROM_LIST_DD.getValue(), 1)) < Number(edt_TO_LIST_DD.getValue())) {
                await $c.win.alert("상장일의 검색 기간은 1년 이내로만 가능합니다.");
                edt_FROM_LIST_DD.focus();
                return false;
            }
        }
    }
    // 코드부여일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_STD_CD_GRNT_DD, edt_TO_STD_CD_GRNT_DD) === false) {
        return false;
    }

    // 발행일 체크
    if ($c.stf.compareFromToDate2(edt_FROM_LIST_DD, edt_TO_LIST_DD) === false) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name gridCtrl
 * @description 체크박스 체크 시 그리드 항목 show
 * @param {*} pObj pObj
 * @returns {void}
 * @hidden N
 */
scwin.gridCtrl = function(pObj) {
    let sColId = pObj.id;
    sColId = sColId.replace("chb_", "");
    const bChecked = pObj.getValue();
    if (bChecked === "Y" && $c.cm.getColumnProp(grd_List, sColId, "Show") !== "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", true);
    } else if (bChecked === "N" && $c.cm.getColumnProp(grd_List, sColId, "Show") === "TRUE") {
        $c.cm.setColumnProp(grd_List, sColId, "Show", false);
    }
    // grd_List.AutoResizeAllCol(true);

};

/**
 * @method
 * @name allUnCheck
 * @description 전체선택 체크 시 나머지 모두 언체크.
 * @returns {void}
 * @hidden N
 */
scwin.allUnCheck = function() {
    const sAllChecked = chb_ALL.getValue();
    const oCheckBoxs = document.getElementsByName("chk");
    for (let nRow = 0; nRow < oCheckBoxs.length; nRow++) {
        oCheckBoxs[nRow].setValue((sAllChecked === "Y") ? true : false);
        scwin.gridCtrl(oCheckBoxs[nRow]);
    }
};

/**
 * @method
 * @name setSrchDt
 * @description set Srch Dt 처리
 * @returns {void}
 * @hidden N
 */
scwin.setSrchDt = function() {
    if (cmb_LIST_STAT_CD.getValue() === "" || cmb_LIST_STAT_CD.getValue() === "D" || cmb_LIST_STAT_CD.getValue() === "N") {
        if ((edt_FROM_ISU_DD.getValue() === "" || edt_TO_ISU_DD.getValue() === "") &&
            (edt_FROM_STD_CD_GRNT_DD.getValue() === "" || edt_TO_STD_CD_GRNT_DD.getValue() === "")) {
            // 기본값 세팅
            scwin.setDefaultVal();
        }
    }
};
